/** The name of a drum number ("Drum sound 130" if it is not in the table). */
export const drumNumberName = (key: number): string => DRUM_MIDI_MAP[key] ?? `Drum sound ${key}`;

/** The highest key the bundled SoundFonts play (General MIDI percussion ends at 87). */
export const LAST_PLAYABLE_DRUM = 87;

/**
 * Numbers the bundled SoundFonts have no sample for (the Guitar Pro articulations
 * above 87, e.g. rim shot or chokes), and the key that sounds closest instead.
 * Applied when the MIDI is generated; the score keeps the original number.
 */
export const DRUM_FALLBACK: Readonly<Record<number, number>> = {
  91: 38, // snare rim shot → snare
  92: 42, // hi-hat half open → closed
  93: 59, // ride edge → ride cymbal 2
  94: 51, // ride choke → ride
  95: 55, // splash choke → splash
  96: 52, // china choke → china
  97: 49, // crash high choke → crash
  98: 57, // crash medium choke → crash 2
  99: 56, // cowbell low → cowbell
  100: 56,
  101: 56,
  102: 56,
  103: 56,
  104: 60, // hand mute → high bongo
  105: 60, // hand slap
  106: 61, // hand mute → low bongo
  107: 61,
  108: 64, // conga low slap → low conga
  109: 64,
  110: 63, // conga high slap → open high conga
  111: 54, // tambourine variants → tambourine
  112: 54,
  113: 54,
  114: 36, // grancassa → kick
  115: 49, // piatti → crash
  116: 49,
  117: 69, // cabasa return → cabasa
  118: 70, // maracas → maracas
  119: 70,
  120: 70,
  122: 82, // shaker return → shaker
  123: 84, // bell tree return → bell tree
  124: 60, // golpe → bongo
  125: 61,
  126: 51, // ride middle / bell (second copies) → ride
  127: 53,
};

/** The key to play for a drum number: itself, or its fallback where the SoundFont is silent. */
export const playableDrumKey = (key: number): number => DRUM_FALLBACK[key] ?? key;
